def gen(rng):
    def rnum(L):
        if L == 1:
            return str(rng.randint(0, 9))
        return str(rng.randint(1, 9)) + ''.join(rng.choice('0123456789') for _ in range(L - 1))
    pairs = [('0', '0'), ('0', '5'), ('5', '0'), ('9', '1'), ('1', '9'), ('99', '1'), ('1', '99'), ('999999', '1'),
             ('123', '456'), ('500', '500'), ('1000', '1'), ('10', '90'), ('456', '77')]
    for _ in range(14):
        pairs.append((rnum(rng.randint(1, 12)), rnum(rng.randint(1, 12))))
    N = 100000
    pairs.append((rnum(N), rnum(N)))
    pairs.append(('9' * N, '1'))
    pairs.append(('9' * N, '9' * N))
    pairs.append((rnum(N), rnum(1)))
    pairs.append(('1' + '0' * (N - 1), '9' * (N - 1)))
    return [a + '\n' + b for a, b in pairs]
